def runs_diag(grid, slope=1):
    # returns dict: for each zero cell, length of its maximal run along direction (1,slope)
    Hh,Ww=grid.shape
    res={}
    for y in range(Hh):
        for x in range(Ww):
            if grid[y,x]!=0: continue
            L=1
            yy,xx=y+1,x+slope
            while 0<=yy<Hh and 0<=xx<Ww and grid[yy,xx]==0: L+=1; yy+=1; xx+=slope
            yy,xx=y-1,x-slope
            while 0<=yy<Hh and 0<=xx<Ww and grid[yy,xx]==0: L+=1; yy-=1; xx-=slope
            res[(y,x)]=L
    return res
